import re

def entities(doc, scope) -> list:
    """Every distinct entity (product) the scope's records are about."""
    prod_node = node_by_title(doc, f"{scope}: Products")
    if not prod_node:
        return []

    results = []
    for row_idx, row in table_rows(prod_node):
        prod_id = row.get('product')
        if prod_id:
            results.append({"id": prod_id, "description": prod_id})
    return results

def recorded_end(doc, scope) -> float or None:
    """The last time point (day) covered by the scope's records."""
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if not ledger_node:
        return None

    max_day = -1
    for row_idx, row in table_rows(ledger_node):
        day_val = row.get('day')
        if day_val:
            try:
                max_day = max(max_day, int(day_val))
            except ValueError:
                pass
    return float(max_day) if max_day != -1 else None

