                    "kind": "shipment",
                    "entities": [prod_id],
                    "value": int(shipped),
                    "src": [ledger_node['node_id'], row_idx, ['shipped']]
                })

            # Backordered
            back = row.get('backordered')
            if back:
                outcomes_list.append({
                    "time": day_f,
                    "kind": "backorder_level",
                    "entities": [prod_id],
                    "value": int(back),
                    "src": [ledger_node['node_id'], row_idx, ['backordered']]
                })

            # Stock
            stock = row.get('stock')
            if stock:
                outcomes_list.append({
                    "time": day_f,
                    "kind": "stock_level",
                    "entities": [prod_id],
                    "value": int(stock),
                    "src": [ledger_node['node_id'], row_idx, ['stock']]
                })

    # 2. Events
    events_node = node_by_title(doc, f"{scope}: Events")
    if events_node:
        if events_node['kind'] == 'list':
            for line_idx, line in enumerate(events_node['lines']):
                # Extract day and product
                day_match = re.search(r'Day (\d+)', line)
                prod_match = re.search(r'([A-Z0-9-]+) runs out of stock|order for ([A-Z0-9-]+)', line)

                if day_match:
                    day_f = float(day_match.group(1))
                    prod_id = None
                    if prod_match:
                        prod_id = prod_match.group(1) or prod_match.group(2)

                    outcomes_list.append({
                        "time": day_f,
                        "kind": "event",
                        "entities": [prod_id] if prod_id else [],
                        "value": None,
                        "src": [events_node['node_id'], line_idx]
                    })
        elif events_node['kind'] == 'text':
            # If text starts with "No events", nothing to add
            pass

    return outcomes_list

def params(doc, scope) -> dict:
    """Constants stated in the document."""
    # The text node for the scope contains the dispatch capacity
    scope_node = node_by_title(doc, scope)
    if not scope_node or scope_node['kind'] != 'text':
        return {}

    text = scope_node['text']
    capacity_match = re.search(r'Daily dispatch capacity: (\d+)\s*kg', text)
    if capacity_match:
        return {"daily_dispatch_capacity": int(capacity_match.group(1))}

    return {}

